<template>
	<div
		ref="rootRef"
		class="ext-sws-language-picker"
		@focusout="closeWhenFocusLeaves"
		@keyup.esc="closeOnEscape"
	>
		<slot
			:expanded="open"
			:controls="panelId"
			:toggle="toggle"
			:close="close"
		/>

		<!-- Shown rather than created, the way a Codex menu is: useFloatingMenu positions an element
			that is already there, and one appearing on open would be painted once where it happens to
			sit before being moved. -->
		<div
			v-show="open"
			:id="panelId"
			ref="panelRef"
			class="ext-sws-language-picker__panel"
			@mousedown="keepFocusInSearch"
		>
			<CdxSearchInput
				v-model="query"
				class="ext-sws-language-picker__search"
				:placeholder="searchPlaceholder"
				:aria-label="searchPlaceholder"
				:aria-controls="menuId"
				:aria-activedescendant="highlightedId"
				aria-autocomplete="list"
				role="combobox"
				aria-expanded="true"
				@keydown="onSearchKeydown"
				@keyup.enter="pickHighlighted"
			/>
			<!-- Out of the tab order: the list is reached with the arrow keys from the search field, and
				a scrollable list Chrome would otherwise stop Tab on has no name and no use there. -->
			<CdxMenu
				:id="menuId"
				ref="menuRef"
				tabindex="-1"
				class="ext-sws-language-picker__menu"
				:selected="props.modelValue"
				:menu-items="menuItems"
				:expanded="open"
				:visible-item-limit="VISIBLE_ITEMS"
				@update:selected="onSelect"
			>
				<template #no-results>
					{{ noResultsLabel }}
				</template>
			</CdxMenu>
		</div>
	</div>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';
import { CdxMenu, CdxSearchInput, useFloatingMenu, useGeneratedId } from '@wikimedia/codex';
import type { MenuItemData } from '@wikimedia/codex';
import {
	languageOptions,
	matchingLanguages,
	shownLanguageTag,
	typedLanguageTag
} from '@/presentation/languages.ts';

// Enough that the list scrolls rather than growing the panel past the dialog it opens inside.
const VISIBLE_ITEMS = 8;

// How many frames to keep trying to put the focus in the search field while the panel is placed.
const FOCUS_ATTEMPTS = 10;

const FOCUSABLE = 'button, [href], input, select, textarea, [tabindex]:not( [tabindex="-1"] )';

interface LanguagePickerProps {
	/** The committed language, as a BCP 47 tag, or null for none. */
	modelValue: string | null;
	/**
	 * The edge of the trigger the panel opens from, so that it reads as belonging to it: the end of a
	 * trigger at the end of a field, the start of one that starts a row.
	 */
	placement: 'bottom-start' | 'bottom-end';
	/** Languages listed but not to be picked, as BCP 47 tags, such as the ones a list already holds. */
	disabledLanguages?: readonly string[];
}

const props = withDefaults( defineProps<LanguagePickerProps>(), {
	disabledLanguages: () => []
} );

const emit = defineEmits<{
	'update:modelValue': [ tag: string ];
}>();

defineSlots<{
	/**
	 * The trigger the panel opens under. Closing the panel hands the focus back to the trigger's
	 * first control.
	 */
	default( props: {
		expanded: boolean;
		controls: string;
		toggle: () => void;
		close: () => void;
	} ): unknown;
}>();

const searchPlaceholder = mw.message( 'sws-language-picker-placeholder' ).text();
const noResultsLabel = mw.message( 'sws-language-picker-no-results' ).text();

const panelId = useGeneratedId( 'ext-sws-language-picker-panel' );
const menuId = useGeneratedId( 'ext-sws-language-picker-menu' );

const rootRef = ref<HTMLElement | null>( null );
const panelRef = ref<HTMLElement | null>( null );
const menuRef = ref<InstanceType<typeof CdxMenu> | null>( null );

const open = ref( false );
const query = ref( '' );

/**
 * The languages to choose from, narrowed by what the user is typing, and none while the panel is
 * closed, since Codex renders every entry it is given, shown or not. A well-formed tag none of
 * them carries is offered as an entry of its own, which is how a language the list lacks (`gsw`)
 * is entered. Every language is therefore chosen rather than typed, so text on its way to a name
 * can never be mistaken for a tag.
 */
const menuItems = computed<MenuItemData[]>( () => {
	if ( !open.value ) {
		return [];
	}

	const typed = query.value.trim();
	const options = languageOptions();

	const items: MenuItemData[] = matchingLanguages( options, typed )
		.map( ( option ) => ( {
			value: option.tag,
			label: option.name,
			supportingText: shownLanguageTag( option.tag ),
			disabled: props.disabledLanguages.includes( option.tag )
		} ) );

	const typedTag = typedLanguageTag( options, typed );

	if ( typedTag !== undefined ) {
		items.push( {
			value: typedTag,
			label: typed,
			description: mw.message( 'sws-language-picker-tag' ).text(),
			disabled: props.disabledLanguages.includes( typedTag )
		} );
	}

	return items;
} );

/**
 * Which entry the arrow keys have reached, for a screen reader to announce while focus stays in
 * the search field. Read back from the rendered list rather than asked of the menu: Codex mints a
 * fresh id for every entry whenever the list changes, so the id it holds for the entry the arrow
 * keys reached names an element the search has already replaced. Watched
 * rather than read in `onUpdated`, which the arrow keys never reach: they move the menu's own
 * state, and the picker around it does not re-render.
 */
const highlightedId = ref<string | undefined>( undefined );

watch(
	[ menuItems, () => menuRef.value?.getHighlightedMenuItem() ],
	() => {
		highlightedId.value = panelRef.value?.querySelector( '.cdx-menu-item--highlighted' )?.id;
	},
	{ flush: 'post' }
);

// The trigger, which the panel opens under. Wrapped the way a component is: handed a bare element,
// Codex 1.14 passes the ref object itself on to floating-ui's autoUpdate, which resolves it to
// nothing, so nothing would watch the trigger.
const anchor = computed( () => rootRef.value === null ? undefined : { $el: rootRef.value } );

// All useFloatingMenu reads of the element it places: whether it is showing, and its root node, by
// `$el` up to Codex 1.x and by getRootElement() from 2.x. It asks by type for a CdxMenu, the
// component it was written against.
const floatingPanel = computed( () => panelRef.value === null ?
	undefined :
	{
		$el: panelRef.value,
		getRootElement: (): HTMLElement | null => panelRef.value,
		isExpanded: (): boolean => open.value
	}
);

/**
 * Set off by enough of a gap that the panel's edge is never mistaken for the field's. Flipping
 * above when there is no room below, clamping to the space left, and hiding when the field scrolls
 * out of the dialog all come with it. The casts are DataExportButtons.vue's, which explains them.
 */
useFloatingMenu(
	anchor as unknown as Parameters<typeof useFloatingMenu>[0],
	floatingPanel as unknown as Parameters<typeof useFloatingMenu>[1],
	{ placement: props.placement, offset: 4 }
);

async function toggle(): Promise<void> {
	if ( open.value ) {
		closeAndReturnFocus();
		return;
	}

	// A search half typed and then dismissed is not an answer to come back to.
	query.value = '';
	open.value = true;

	await nextTick();
	await focusSearch();
}

/**
 * useFloatingMenu shows the panel only once it has placed it, a frame or more after the panel
 * opens, and a field in a hidden panel cannot take the focus. So the focus is tried each frame
 * until it takes, which on a first open below the fold is not the first try. The scroll it would
 * make is left out: that would read as the dialog scrolling, which closes the panel.
 */
async function focusSearch(): Promise<void> {
	const input = panelRef.value?.querySelector( 'input' );

	if ( !input ) {
		return;
	}

	for ( let attempt = 0; attempt < FOCUS_ATTEMPTS && open.value; attempt++ ) {
		input.focus( { preventScroll: true } );

		if ( document.activeElement === input ) {
			return;
		}

		await nextFrame();
	}
}

function nextFrame(): Promise<void> {
	return new Promise( ( resolve ) => {
		requestAnimationFrame( () => resolve() );
	} );
}

function close(): void {
	open.value = false;
}

function closeAndReturnFocus(): void {
	close();
	focusTrigger();
}

// Without scrolling: the trigger may be scrolled out of view, as when the dialog scrolling is what
// closed the panel.
function focusTrigger(): void {
	rootRef.value?.querySelector<HTMLElement>( FOCUSABLE )?.focus( { preventScroll: true } );
}

defineExpose( { focusTrigger } );

/**
 * Escape closes the panel wherever the focus is in the picker, and goes no further: Codex dialogs
 * close on the Escape keyup, which would take everything typed into the dialog with it. With the
 * panel closed, Escape is the dialog's as usual. The Escape that cancels an IME composition is
 * not a cancel.
 */
function closeOnEscape( event: KeyboardEvent ): void {
	if ( !open.value || event.isComposing ) {
		return;
	}

	event.stopPropagation();
	closeAndReturnFocus();
}

/**
 * The menu owns the arrow keys. Space is the field's, since a language name may contain one, and
 * Escape is the picker's; a bare Home or End never arrives, CdxTextInput keeping those for the
 * text. Enter picks on its keyup, like Escape closes on its: picking on the keydown would hand the
 * focus back to the trigger, and a button clicks itself on the Enter keyup that then lands on it,
 * which would open the panel straight back up. Its keydown does nothing, not even submit a form
 * the dialog might hold.
 */
function onSearchKeydown( event: KeyboardEvent ): void {
	if ( event.key === 'Enter' ) {
		event.preventDefault();
		return;
	}

	if ( event.key === ' ' || event.key === 'Escape' ) {
		return;
	}

	menuRef.value?.delegateKeyNavigation( event );
}

// The Enter that ends an IME composition is not a pick.
function pickHighlighted( event: KeyboardEvent ): void {
	if ( !event.isComposing ) {
		menuRef.value?.delegateKeyNavigation( event );
	}
}

/**
 * Only a language the list is offering is a pick: Codex holds the entry the arrow keys reached as
 * a snapshot and never re-resolves it against the entries, so Enter or Tab would otherwise choose
 * a language the search has since hidden. That snapshot is also why `highlightedId` reads the id
 * back from the list. CdxMenu reports the language the picker already holds when that one is
 * picked again, which still ends the choice.
 */
function onSelect( tag: string | null ): void {
	if ( tag === null || !menuItems.value.some( ( item ) => item.value === tag ) ) {
		return;
	}

	closeAndReturnFocus();

	if ( tag !== props.modelValue ) {
		emit( 'update:modelValue', tag );
	}
}

/**
 * Focus leaving the picker for somewhere else on the page is the user done with it. Focus going
 * nowhere is left alone: that is the window losing focus, and the panel waits for the user's
 * return, while a press elsewhere on the page closes it from onDocumentMousedown.
 */
function closeWhenFocusLeaves( event: FocusEvent ): void {
	if ( event.relatedTarget instanceof Node && !rootRef.value?.contains( event.relatedTarget ) ) {
		close();
	}
}

/**
 * A press anywhere in the panel but its search field, such as on the field's icon or on the menu's
 * scrollbar in Firefox, would move the focus out of the panel, and so close it. Codex prevents that
 * on its menu items only.
 */
function keepFocusInSearch( event: MouseEvent ): void {
	if ( !( event.target instanceof HTMLInputElement ) ) {
		event.preventDefault();
	}
}

// mousedown rather than click: a pointer that goes down outside and up inside must not read as
// having stayed inside.
function onDocumentMousedown( event: MouseEvent ): void {
	if ( !rootRef.value?.contains( event.target as Node ) ) {
		close();
	}
}

/**
 * Scrolling what the picker sits in moves the trigger away from under its panel, and once it
 * leaves the visible area useFloatingMenu hides the panel, which drops the focus in it to the
 * page. So the panel closes instead, handing the focus back to the trigger, which scrolling does not
 * take it from. Only something the picker sits inside counts as that: the panel's own list
 * scrolling is the user browsing it, and a text field left behind scrolls its text back to the
 * start, which is not the page moving at all.
 */
function closeOnScroll( event: Event ): void {
	if ( event.target instanceof Node && event.target.contains( rootRef.value ) ) {
		closeAndReturnFocus();
	}
}

// Listened for only while the panel is open: every row of a field has a picker of its own, and a
// closed one has nothing to close.
watch( open, ( isOpen ) => {
	if ( isOpen ) {
		document.addEventListener( 'mousedown', onDocumentMousedown );
		// Captured, since scroll events do not bubble.
		document.addEventListener( 'scroll', closeOnScroll, true );
	} else {
		stopListeningToThePage();
	}
} );

onBeforeUnmount( stopListeningToThePage );

function stopListeningToThePage(): void {
	document.removeEventListener( 'mousedown', onDocumentMousedown );
	document.removeEventListener( 'scroll', closeOnScroll, true );
}
</script>

<style lang="less">
@import ( reference ) '@wikimedia/codex-design-tokens/theme-wikimedia-ui.less';

.ext-sws-language-picker {
	/* As wide as the trigger, which the panel opens under, and a flex container so an inline-block
		trigger gets no line box to stand taller in. */
	display: flex;
	width: fit-content;

	/* A long name wraps; its tag moves to the next line whole rather than breaking at a hyphen. */
	&__menu .cdx-menu-item__text__supporting-text {
		white-space: nowrap;
	}

	/* Frameless: the search field and the menu under it draw their own borders, and a second one
		around both reads as a box inside a box. Its position, width, max-height and visibility are
		written onto it by useFloatingMenu, which sizes it to the trigger; the floor is ours, wide
		enough for a search field and the names under it. */
	&__panel {
		position: absolute;
		z-index: @z-index-dropdown;
		box-sizing: @box-sizing-base;
		min-width: @size-1600;
		box-shadow: @box-shadow-drop-medium;
		display: flex;
		flex-direction: column;
		background-color: @background-color-base;
		/* useFloatingMenu clamps the panel's height to the room left in the viewport. The list is what
			gives way, scrolling within what is left under the search field. */
		overflow: hidden;
	}

	&__search {
		flex: none;
	}

	/* Codex floats a menu under the field it belongs to. Here it is the lower half of the panel
		instead, so it goes back into the flow, and its height becomes part of the panel's. The field
		is the top of one shape and the menu the bottom of it, so the menu's top corners are square,
		as the field's are, and the two borders between them collapse into the one line. */
	&__menu.cdx-menu {
		position: static;
		border-start-start-radius: 0;
		border-start-end-radius: 0;
		flex: 1 1 auto;
		min-height: 0;
		max-width: none;
		margin-block-start: -@border-width-base;
		box-shadow: none;

		.cdx-menu__listbox {
			min-height: 0;
		}
	}
}
</style>
