import type { LocalizedIdentity } from './LocalizedIdentity';
import { SubjectId } from '@/domain/SubjectId';
import type { StatementList } from '@/domain/StatementList';
import type { Schema, SchemaName } from '@/domain/Schema';
import { PageSubjects } from '@/domain/PageSubjects';
import { Subject } from '@/domain/Subject';
import { PageIdentifiers } from '@/domain/PageIdentifiers';
import type { DeserializedPageSubjects } from '@/persistence/PageSubjectsDeserializer';
import type { SubjectViolation } from '@/domain/SubjectViolation';

export interface SubjectWithReferencedSubjects {
	requestedSubject: Subject;
	referencedSubjects: Subject[];
	/** The targets of the requested Subject's relations that the read found no Subject for. */
	notFoundTargetIds: SubjectId[];
}

/**
 * A Subject pointing at the one that was asked about, together with the properties through which it
 * does, in the order that Subject holds them.
 */
export interface ReferencingSubject {
	subject: Subject;
	propertyNames: string[];
}

export interface ReferencingSubjects {
	subjects: ReferencingSubject[];
	/** Whether the wiki holds further referencing Subjects beyond those returned. */
	truncated: boolean;
}

/**
 * What a Subject write returns.
 */
export interface SubjectWriteResult {
	/** The id the server assigned or confirmed. Always known. */
	subjectId: SubjectId;
	/**
	 * The Subject as the server persisted it, carrying the normalisation, and for a create the page,
	 * that a client-built copy cannot reproduce. Null when the response omitted the page identifiers,
	 * which a Subject on an unresolvable page does: recording it would put a Subject with no page
	 * behind links that need one, so callers keep whatever copy they already had.
	 */
	subject: Subject | null;
	/**
	 * The Schema the Subject instantiates, so a display can render values saved against a
	 * property the Schema gained out of band. Null when the server could not resolve it.
	 */
	schema: Schema | null;
}

/**
 * What creating a Subject together with a page of its own returns, on top of the write itself: the
 * page created, which the caller has not named and cannot derive - a label may title no page, and
 * the wiki normalizes the titles it does.
 */
export interface SubjectPageWriteResult extends SubjectWriteResult {
	pageTitle: string;
	/** So a caller can go on to store further Subjects on the page this write created. */
	pageId: number;
}

export interface SubjectRepository {

	getSubject( id: SubjectId ): Promise<Subject>;

	/**
	 * The Subject as an editor must see it: the hosting page's current revision, rather than the
	 * revision the wiki publishes, which on a wiki with an approval extension is an older one.
	 * Saving what getSubject returns there would overwrite the draft with approved values.
	 */
	getSubjectForEditing( id: SubjectId ): Promise<Subject>;

	/**
	 * Returns the Subject together with the Subjects its relations target,
	 * so relation labels can be shown without fetching each target individually.
	 * Referenced Subjects that cannot be loaded are omitted rather than failing the whole call.
	 */
	getSubjectWithReferencedSubjects( id: SubjectId ): Promise<SubjectWithReferencedSubjects>;

	/**
	 * The Subjects whose relations point at this one; the opposite direction of
	 * getSubjectWithReferencedSubjects.
	 */
	getReferencingSubjects( id: SubjectId ): Promise<ReferencingSubjects>;

	getPageSubjects( pageId: number ): Promise<DeserializedPageSubjects>;

	setMainSubject( pageId: number, subjectId: SubjectId | null, comment?: string ): Promise<void>;

	setSubjectsOrdering(
		pageId: number,
		mainSubjectId: SubjectId | null,
		otherSubjectIds: SubjectId[],
		comment?: string
	): Promise<void>;

	/**
	 * The optional id is a pre-minted, unused Subject ID to assign, as on createOtherSubject. The
	 * dependentSubjects are written as on updateSubject.
	 */
	createMainSubject(
		pageId: number,
		label: string | null,
		schemaName: SchemaName,
		statements: StatementList,
		dependentSubjects: readonly Subject[],
		comment?: string,
		id?: SubjectId,
		identity?: LocalizedIdentity | null,
	): Promise<SubjectWriteResult>;

	/**
	 * The optional id is a pre-minted, unused Subject ID to assign; omit it to have the server mint
	 * one. Minting up front (see mintSubjectId) is what lets relations between Subjects be wired
	 * before any of them exists. The dependentSubjects are written as on updateSubject.
	 */
	createOtherSubject(
		pageId: number,
		label: string | null,
		schemaName: SchemaName,
		statements: StatementList,
		dependentSubjects: readonly Subject[],
		comment?: string,
		id?: SubjectId,
		identity?: LocalizedIdentity | null,
	): Promise<SubjectWriteResult>;

	/**
	 * Creates a Subject together with a page of its own, in one revision, with the Subject as that
	 * page's Main Subject. The page is titled by pageTitle, by the label where there is no
	 * pageTitle, and by the Subject's own ID when the label titles no page. Throws
	 * PageTitleTakenError when a page of that title already exists, and InvalidPageTitleError when
	 * the pageTitle given titles no page; nothing is created then.
	 *
	 * The optional id is a pre-minted, unused Subject ID to assign, as on createOtherSubject. The
	 * dependentSubjects are written as on updateSubject.
	 */
	createSubjectPage(
		label: string | null,
		schemaName: SchemaName,
		statements: StatementList,
		dependentSubjects: readonly Subject[],
		comment?: string,
		pageTitle?: string,
		id?: SubjectId,
		identity?: LocalizedIdentity | null,
	): Promise<SubjectPageWriteResult>;

	/**
	 * An unused Subject ID, minted without creating any Subject. Stateless: the ID is not
	 * reserved, so a caller that never uses it costs nothing.
	 */
	mintSubjectId(): Promise<SubjectId>;

	/**
	 * Writes the dependentSubjects to the Subject's page in the same revision, each creating or replacing the
	 * Subject with its id. The write removes the Dependent Subjects it leaves unreached.
	 */
	updateSubject(
		id: SubjectId,
		label: string | null,
		statements: StatementList,
		dependentSubjects: readonly Subject[],
		comment?: string,
		identity?: LocalizedIdentity | null,
	): Promise<SubjectWriteResult>;

	deleteSubject( id: SubjectId, comment?: string ): Promise<boolean>;

	/**
	 * Moves a Subject to another page, keeping its id so relations targeting it keep resolving.
	 * Edits both pages. With makeMainSubject the target page's current Main Subject is demoted to
	 * one of the page's other Subjects.
	 */
	moveSubject( id: SubjectId, targetPageId: number, makeMainSubject: boolean, comment?: string ): Promise<void>;

	validateSubject( label: string | null, schemaName: SchemaName, statements: StatementList ): Promise<SubjectViolation[]>;

	validateSubjectUpdate( id: SubjectId, label: string | null, statements: StatementList ): Promise<SubjectViolation[]>;

}

export class StubSubjectRepository implements SubjectRepository {

	private readonly subjects: Map<string, Subject> = new Map();

	public constructor( subjects: Subject[] ) {
		for ( const subject of subjects ) {
			this.subjects.set( subject.getId().text, subject );
		}
	}

	public async getSubject( id: SubjectId ): Promise<Subject> {
		const subject = this.subjects.get( id.text );

		if ( subject === undefined ) {
			throw new Error( `Subject with id ${ id.text } not found` );
		}

		return subject;
	}

	public getSubjectForEditing( id: SubjectId ): Promise<Subject> {
		return this.getSubject( id );
	}

	public async getSubjectWithReferencedSubjects( id: SubjectId ): Promise<SubjectWithReferencedSubjects> {
		const subject = await this.getSubject( id );
		const referencedIds = [ ...subject.getStatements().getIdsOfReferencedSubjects() ];

		return {
			requestedSubject: subject,
			referencedSubjects: [ ...new Set( referencedIds.map( ( referencedId ) => referencedId.text ) ) ]
				.map( ( referencedId ) => this.subjects.get( referencedId ) )
				.filter( ( referenced ): referenced is Subject => referenced !== undefined ),
			notFoundTargetIds: referencedIds.filter( ( referencedId ) => !this.subjects.has( referencedId.text ) ),
		};
	}

	public getReferencingSubjects( _id: SubjectId ): Promise<ReferencingSubjects> {
		return Promise.resolve( { subjects: [], truncated: false } );
	}

	public getPageSubjects( pageId: number ): Promise<DeserializedPageSubjects> {
		return Promise.resolve( {
			pageSubjects: new PageSubjects( pageId, null, [] ),
			referencedSubjects: [],
			notFoundTargetIds: [],
			schemas: [],
		} );
	}

	public setMainSubject( _pageId: number, _subjectId: SubjectId | null, _comment?: string ): Promise<void> {
		return Promise.resolve();
	}

	public setSubjectsOrdering(
		_pageId: number,
		_mainSubjectId: SubjectId | null,
		_otherSubjectIds: SubjectId[],
		_comment?: string,
	): Promise<void> {
		return Promise.resolve();
	}

	public createMainSubject( pageId: number, label: string | null, schemaName: string, statements: StatementList, _dependentSubjects: readonly Subject[], _comment?: string, id?: SubjectId ): Promise<SubjectWriteResult> {
		return Promise.resolve( this.newWriteResult( id ?? new SubjectId( 's11111111111111' ), pageId, label, schemaName, statements ) );
	}

	public createOtherSubject( pageId: number, label: string | null, schemaName: string, statements: StatementList, _dependentSubjects: readonly Subject[], _comment?: string, id?: SubjectId ): Promise<SubjectWriteResult> {
		return Promise.resolve( this.newWriteResult( id ?? new SubjectId( 's11111111111112' ), pageId, label, schemaName, statements ) );
	}

	public createSubjectPage( label: string | null, schemaName: string, statements: StatementList, _dependentSubjects: readonly Subject[], _comment?: string, pageTitle?: string, id?: SubjectId ): Promise<SubjectPageWriteResult> {
		const createdId = id ?? new SubjectId( 's11111111111113' );

		return Promise.resolve( {
			...this.newWriteResult( createdId, 1, label, schemaName, statements ),
			pageTitle: pageTitle ?? label ?? createdId.text,
			pageId: 1,
		} );
	}

	public mintSubjectId(): Promise<SubjectId> {
		return Promise.resolve( new SubjectId( 'smintedAAAAAAA1' ) );
	}

	public async updateSubject( id: SubjectId, label: string | null, statements: StatementList, _dependentSubjects: readonly Subject[], _comment?: string ): Promise<SubjectWriteResult> {
		const existing = await this.getSubject( id );

		return this.newWriteResult( id, 0, label, existing.getSchemaName(), statements );
	}

	private newWriteResult(
		id: SubjectId,
		pageId: number,
		label: string | null,
		schemaName: string,
		statements: StatementList,
	): SubjectWriteResult {
		return {
			subjectId: id,
			subject: new Subject( id, label, label ?? schemaName, label === null, schemaName, statements, new PageIdentifiers( pageId, 'page-title' ), null ),
			schema: null,
		};
	}

	public deleteSubject( id: SubjectId, _comment?: string ): Promise<boolean> {
		return Promise.resolve( this.subjects.delete( id.text ) );
	}

	public moveSubject( _id: SubjectId, _targetPageId: number, _makeMainSubject: boolean, _comment?: string ): Promise<void> {
		return Promise.resolve();
	}

	public validateSubject( _label: string | null, _schemaName: SchemaName, _statements: StatementList ): Promise<SubjectViolation[]> {
		return Promise.resolve( [] );
	}

	public validateSubjectUpdate( _id: SubjectId, _label: string | null, _statements: StatementList ): Promise<SubjectViolation[]> {
		return Promise.resolve( [] );
	}

}
