import type { LocalizedIdentity } from '@/domain/LocalizedIdentity';
import type {
	ReferencingSubject,
	ReferencingSubjects,
	SubjectPageWriteResult,
	SubjectRepository,
	SubjectWithReferencedSubjects,
	SubjectWriteResult,
} from '@/domain/SubjectRepository';
import { SubjectId } from '@/domain/SubjectId';
import type { SubjectDeserializer } from '@/persistence/SubjectDeserializer';
import {
	PageSubjectsDeserializer,
	type DeserializedPageSubjects,
	type PageSubjectsJson,
} from '@/persistence/PageSubjectsDeserializer';
import { StatementList, statementsToJson } from '@/domain/StatementList';
import { type SchemaName } from '@/domain/Schema';
import { type SchemaReference, schemaReferenceName } from '@/domain/SchemaReference';
import { SchemaDeserializer } from '@/persistence/SchemaDeserializer';
import type { HttpClient } from '@/infrastructure/HttpClient/HttpClient';
import type { Subject } from '@/domain/Subject';
import type { SubjectViolation } from '@/domain/SubjectViolation';
import { ValidationFailedError } from '@/persistence/ValidationFailedError';
import { SubjectIdInUseError } from '@/persistence/SubjectIdInUseError';
import { SubjectNotFoundError } from '@/persistence/SubjectNotFoundError';
import { PageTitleTakenError } from '@/persistence/PageTitleTakenError';
import { InvalidPageTitleError } from '@/persistence/InvalidPageTitleError';
import { parseViolations } from '@/persistence/violationParsing';
import { notFoundTargetIds } from '@/persistence/notFoundTargetIds';

async function throwOn422IfPossible( response: Response ): Promise<void> {
	if ( response.status !== 422 ) {
		return;
	}
	let body: unknown;
	try {
		body = await response.clone().json();
	} catch {
		// Body wasn't valid JSON — fall through to the generic-error path.
		return;
	}
	const violations = parseViolations( body );
	if ( violations === null ) {
		console.error(
			'RestSubjectRepository: malformed 422 body, falling through to generic error',
			body,
		);
		return;
	}
	throw new ValidationFailedError( violations );
}

function dependentSubjectsField( subjects: readonly Subject[] ): { dependentSubjects?: Record<string, unknown>[] } {
	if ( subjects.length === 0 ) {
		return {};
	}

	return {
		dependentSubjects: subjects.map( ( subject ) => ( {
			id: subject.getId().text,
			schema: subject.getSchemaReference(),
			... subject.getIdentity(),
			statements: statementsToJson( subject.getStatements() ),
			...( subject.getStatements().fieldKeyVersion === undefined ? {} : { fieldKeyVersion: subject.getStatements().fieldKeyVersion } ),
			...( Object.keys( subject.getStatements().fieldNotes ).length || subject.getStatements().notesEdited ? { fieldNotes: subject.getStatements().fieldNotes } : {} ),
		} ) ),
	};
}

export type SubjectJson = {
	id: string;
	/** The stored label, null for a Subject that has none. */
	label: string | null;
	/** The stored label, or the fallback name the server derived when there is none. */
	displayName: string;
	/** Whether displayName fell back to the Schema name, the one tier nobody chose. */
	displayNameIsGenerated: boolean;
	statements: Record<string, unknown>;
	/** A name for a Schema of this wiki, the `{source, name}` object for one from elsewhere (ADR 23). */
	schema: SchemaReference;
	pageId: number;
	pageTitle: string;
	requestedId: string;
	value?: unknown;
};

type SubjectBundleJson = {
	requestedId: string;
	subjects: Record<string, SubjectJson>;
};

type ReferencingSubjectsJson = {
	referencingSubjects: { subject: SubjectJson; propertyNames: string[] }[];
	truncated: boolean;
};

type SubjectWriteResponseJson = {
	subject: SubjectJson;
	schema?: Record<string, unknown>;
};

export class RestSubjectRepository implements SubjectRepository {

	public constructor(
		private readonly mediaWikiRestApiUrl: string,
		private readonly httpClient: HttpClient,
		private readonly subjectDeserializer: SubjectDeserializer,
		private readonly schemaDeserializer: SchemaDeserializer,
		private readonly revisionId?: number,
	) {
	}

	/**
	 * A write answers with the Subject as persisted and the Schema it instantiates. The Schema
	 * name is not repeated in the schema body — it is the Subject's own `schema` field.
	 *
	 * The page identifiers are omitted when the server could not resolve the Subject's page.
	 * Deserializing that would mint a Subject whose page id is undefined, which anything
	 * rendering a link to it would then follow; report no Subject instead, so the caller keeps
	 * the copy it already had.
	 */
	private deserializeWriteResult( json: SubjectWriteResponseJson ): SubjectWriteResult {
		const hasPageContext = json.subject.pageId !== undefined && json.subject.pageTitle !== undefined;

		return {
			subjectId: new SubjectId( json.subject.id ),
			subject: hasPageContext ? this.subjectDeserializer.deserialize( json.subject ) : null,
			schema: json.schema === undefined ?
				null :
				this.schemaDeserializer.deserialize( schemaReferenceName( json.subject.schema ), json.schema ),
		};
	}

	public async getPageSubjects( pageId: number ): Promise<DeserializedPageSubjects> {
		const response = await this.httpClient.get(
			`${ this.mediaWikiRestApiUrl }/sws/v0/page/${ pageId }/subjects?expand=schemas%7Crelations`,
		);

		if ( !response.ok ) {
			throw new Error( 'Error fetching page subjects' );
		}

		const data = await response.json() as PageSubjectsJson;
		return new PageSubjectsDeserializer( this.subjectDeserializer ).deserialize( data );
	}

	public async setMainSubject( pageId: number, subjectId: SubjectId | null, comment?: string ): Promise<void> {
		const response = await this.httpClient.put(
			`${ this.mediaWikiRestApiUrl }/sws/v0/page/${ pageId }/mainSubject`,
			{
				subjectId: subjectId === null ? null : subjectId.text,
				comment,
			},
		);

		if ( !response.ok ) {
			throw new Error( 'Error setting main subject' );
		}
	}

	public async setSubjectsOrdering(
		pageId: number,
		mainSubjectId: SubjectId | null,
		otherSubjectIds: SubjectId[],
		comment?: string,
	): Promise<void> {
		const response = await this.httpClient.put(
			`${ this.mediaWikiRestApiUrl }/sws/v0/page/${ pageId }/subjectsOrdering`,
			{
				mainSubjectId: mainSubjectId === null ? null : mainSubjectId.text,
				otherSubjectIds: otherSubjectIds.map( ( id ) => id.text ),
				comment,
			},
		);

		if ( !response.ok ) {
			throw new Error( 'Error setting subjects ordering' );
		}
	}

	public async getSubject( id: SubjectId ): Promise<Subject> {
		return this.deserializeRequested( await this.fetchSubjectBundle( id, false ) );
	}

	public async getSubjectForEditing( id: SubjectId ): Promise<Subject> {
		return this.deserializeRequested( await this.fetchSubjectBundle( id, true ) );
	}

	private deserializeRequested( bundle: SubjectBundleJson ): Subject {
		return this.subjectDeserializer.deserialize( bundle.subjects[ bundle.requestedId ] );
	}

	/**
	 * The `expand=relations` response bundles the requested Subject together with
	 * every Subject its relations target, so a View can resolve relation labels
	 * without re-fetching each target individually.
	 *
	 * Referenced Subjects that fail to deserialize are skipped: a broken relation
	 * target should not prevent the requested Subject from loading.
	 */
	public async getSubjectWithReferencedSubjects( id: SubjectId ): Promise<SubjectWithReferencedSubjects> {
		const bundle = await this.fetchSubjectBundle( id, false );
		const requestedSubject = this.deserializeRequested( bundle );

		return {
			requestedSubject,
			referencedSubjects: this.deserializeReferencedSubjects( bundle ),
			// A read of an earlier revision leaves out the targets created since, which exist all the same.
			notFoundTargetIds: this.revisionId === undefined ?
				notFoundTargetIds( [ requestedSubject ], Object.keys( bundle.subjects ) ) :
				[],
		};
	}

	/**
	 * The Subjects pointing at this one. Asked for at the endpoint's maximum, since the page shows
	 * the whole list rather than paging through it, and answers `truncated` past that.
	 *
	 * An entry that fails to deserialize is skipped, like a relation target that does: one Subject
	 * the client cannot read should not cost the reader the rest of the list.
	 */
	public async getReferencingSubjects( id: SubjectId ): Promise<ReferencingSubjects> {
		const response = await this.httpClient.get(
			`${ this.mediaWikiRestApiUrl }/sws/v0/subject/${ id.text }/referencingSubjects?limit=50`,
		);

		if ( !response.ok ) {
			throw new Error( 'Error fetching referencing subjects' );
		}

		const data = await response.json() as ReferencingSubjectsJson;

		return {
			subjects: data.referencingSubjects
				.map( ( entry ) => {
					const subject = this.deserializeOrNull( entry.subject );

					return subject === null ? null : { subject, propertyNames: entry.propertyNames };
				} )
				.filter( ( entry ): entry is ReferencingSubject => entry !== null ),
			truncated: data.truncated,
		};
	}

	private deserializeReferencedSubjects( bundle: SubjectBundleJson ): Subject[] {
		return Object.entries( bundle.subjects )
			.filter( ( [ id ] ) => id !== bundle.requestedId )
			.map( ( [ , subjectData ] ) => this.deserializeOrNull( subjectData ) )
			.filter( ( subject ): subject is Subject => subject !== null );
	}

	private deserializeOrNull( subjectData: SubjectJson ): Subject|null {
		try {
			return this.subjectDeserializer.deserialize( subjectData );
		} catch ( _error ) {
			return null;
		}
	}

	/**
	 * A write targets the page's current revision whatever revision was read, so an editing read is
	 * never pinned. SWSApp offers no editing on a pinned view, but a host that mounts an editor
	 * itself has nothing stopping it. An editing read also asks for the requested Subject alone:
	 * `latest` refuses `expand=relations`, and the editor uses nothing else from the bundle.
	 */
	private async fetchSubjectBundle( id: SubjectId, latest: boolean ): Promise<SubjectBundleJson> {
		let url = `${ this.mediaWikiRestApiUrl }/sws/v0/subject/${ id.text }`;

		if ( latest ) {
			url += '?expand=page&latest=1';
		} else if ( this.revisionId !== undefined ) {
			url += `?expand=page|relations&revisionId=${ this.revisionId }`;
		} else {
			url += '?expand=page|relations';
		}

		const response = await this.httpClient.get( url );

		if ( !response.ok ) {
			throw new Error( 'Error fetching subject' );
		}

		const data = await response.json() as { requestedId?: string; subjects?: Record<string, SubjectJson> };

		if ( !data.requestedId || !data.subjects || !data.subjects[ data.requestedId ] ) {
			throw new SubjectNotFoundError( id.text );
		}

		return { requestedId: data.requestedId, subjects: data.subjects };
	}

	/**
	 * Unlike createOtherSubject, a 409 stays a failure even for a minted id: the endpoint also
	 * answers 409 when the page has gained a Main Subject meanwhile, so it does not show that this
	 * very create landed.
	 */
	public async createMainSubject(
		pageId: number,
		label: string | null,
		schemaName: SchemaName,
		statements: StatementList,
		dependentSubjects: readonly Subject[],
		comment?: string,
		id?: SubjectId,
		identity?: LocalizedIdentity | null,
	): Promise<SubjectWriteResult> {
		const payload = {
			label: label,
			... identity,
			schema: schemaName,
			statements: statementsToJson( statements ),
			...( statements.fieldKeyVersion === undefined ? {} : { fieldKeyVersion: statements.fieldKeyVersion } ),
			...( Object.keys( statements.fieldNotes ).length || statements.notesEdited ? { fieldNotes: statements.fieldNotes } : {} ),
			comment,
			id: id?.text,
			...dependentSubjectsField( dependentSubjects ),
		};

		const response = await this.httpClient.post(
			`${ this.mediaWikiRestApiUrl }/sws/v0/page/${ pageId }/mainSubject`,
			payload,
		);

		await throwOn422IfPossible( response );

		if ( !response.ok ) {
			throw new Error( 'Error creating main subject' );
		}

		return this.deserializeWriteResult( await response.json() as SubjectWriteResponseJson );
	}

	public async createOtherSubject(
		pageId: number,
		label: string | null,
		schemaName: SchemaName,
		statements: StatementList,
		dependentSubjects: readonly Subject[],
		comment?: string,
		id?: SubjectId,
		identity?: LocalizedIdentity | null,
	): Promise<SubjectWriteResult> {
		const payload = {
			label: label,
			... identity,
			schema: schemaName,
			statements: statementsToJson( statements ),
			...( statements.fieldKeyVersion === undefined ? {} : { fieldKeyVersion: statements.fieldKeyVersion } ),
			...( Object.keys( statements.fieldNotes ).length || statements.notesEdited ? { fieldNotes: statements.fieldNotes } : {} ),
			comment,
			id: id?.text,
			...dependentSubjectsField( dependentSubjects ),
		};

		const response = await this.httpClient.post(
			`${ this.mediaWikiRestApiUrl }/sws/v0/page/${ pageId }/subjects`,
			payload,
		);

		await throwOn422IfPossible( response );

		if ( response.status === 409 && id !== undefined ) {
			throw new SubjectIdInUseError( id.text );
		}

		if ( !response.ok ) {
			throw new Error( 'Error creating other subject' );
		}

		return this.deserializeWriteResult( await response.json() as SubjectWriteResponseJson );
	}

	public async createSubjectPage(
		label: string | null,
		schemaName: SchemaName,
		statements: StatementList,
		dependentSubjects: readonly Subject[],
		comment?: string,
		pageTitle?: string,
		id?: SubjectId,
		identity?: LocalizedIdentity | null,
	): Promise<SubjectPageWriteResult> {
		let response: Response;

		// A create can fail for reasons the user can act on - the page is protected, the write did
		// not land - so the server's own message is carried through rather than collapsed into a
		// status code. Which of the two paths below carries it depends on the status: the
		// production client resolves 409 and 422 and rejects the rest.
		try {
			response = await this.httpClient.post(
				`${ this.mediaWikiRestApiUrl }/sws/v0/subjects`,
				{
					label: label,
					... identity,
					pageTitle,
					schema: schemaName,
					statements: statementsToJson( statements ),
			...( statements.fieldKeyVersion === undefined ? {} : { fieldKeyVersion: statements.fieldKeyVersion } ),
					...( Object.keys( statements.fieldNotes ).length || statements.notesEdited ? { fieldNotes: statements.fieldNotes } : {} ),
					comment,
					id: id?.text,
					...dependentSubjectsField( dependentSubjects ),
				},
			);
		} catch ( error ) {
			const refusedTitle = this.refusedPageTitleOf( error );

			if ( refusedTitle !== null ) {
				throw new InvalidPageTitleError( refusedTitle );
			}

			throw new Error( this.rejectedMessageOf( error ) ?? 'Error creating subject page' );
		}

		await throwOn422IfPossible( response );

		if ( response.status === 409 ) {
			// Both conflicts answer 409, and only the title one names a title.
			const takenTitle = await this.stringFieldOf( response, 'pageTitle' );

			if ( takenTitle === null && id !== undefined ) {
				throw new SubjectIdInUseError( id.text );
			}

			throw new PageTitleTakenError( takenTitle ?? '' );
		}

		if ( !response.ok ) {
			throw new Error( await this.stringFieldOf( response, 'message' ) ?? 'Error creating subject page' );
		}

		const json = await response.json() as SubjectWriteResponseJson & { pageTitle: string; pageId: number };

		return { ...this.deserializeWriteResult( json ), pageTitle: json.pageTitle, pageId: json.pageId };
	}

	public async mintSubjectId(): Promise<SubjectId> {
		const response = await this.httpClient.post(
			`${ this.mediaWikiRestApiUrl }/sws/v0/subject-ids`,
			{ count: 1 },
		);

		if ( !response.ok ) {
			throw new Error( 'Error minting a subject id' );
		}

		const data = await response.json() as { subjectIds?: string[] };
		const id = data.subjectIds?.[ 0 ];

		if ( id === undefined ) {
			throw new Error( 'Error minting a subject id: the response carried none' );
		}

		return new SubjectId( id );
	}

	/**
	 * A full replacement: a null label clears whatever label the Subject had.
	 */
	public async updateSubject(
		id: SubjectId,
		label: string | null,
		statements: StatementList,
		dependentSubjects: readonly Subject[],
		comment?: string,
		identity?: LocalizedIdentity | null,
	): Promise<SubjectWriteResult> {
		const response = await this.httpClient.put(
			`${ this.mediaWikiRestApiUrl }/sws/v0/subject/${ id.text }`,
			{
				... identity,
				label,
				statements: statementsToJson( statements ),
			...( statements.fieldKeyVersion === undefined ? {} : { fieldKeyVersion: statements.fieldKeyVersion } ),
				...( Object.keys( statements.fieldNotes ).length || statements.notesEdited ? { fieldNotes: statements.fieldNotes } : {} ),
				comment,
				...dependentSubjectsField( dependentSubjects ),
			},
		);

		await throwOn422IfPossible( response );

		if ( !response.ok ) {
			throw new Error( 'Error updating subject' );
		}

		return this.deserializeWriteResult( await response.json() as SubjectWriteResponseJson );
	}

	public async deleteSubject( id: SubjectId, comment?: string ): Promise<boolean> {
		const response = await this.httpClient.delete(
			`${ this.mediaWikiRestApiUrl }/sws/v0/subject/${ id.text }`,
			{ data: { comment } },
		);

		if ( !response.ok ) {
			throw new Error( 'Error deleting subject' );
		}

		return true;
	}

	public async moveSubject(
		id: SubjectId,
		targetPageId: number,
		makeMainSubject: boolean,
		comment?: string,
	): Promise<void> {
		let response: Response;

		// A move can fail for reasons the user can act on - the target page is protected, the Subject
		// is already there - so the server's own message is carried through rather than collapsed into
		// a status code. Which of the two paths below carries it depends on the status: the production
		// client resolves 409 and 422 and rejects the rest.
		try {
			response = await this.httpClient.post(
				`${ this.mediaWikiRestApiUrl }/sws/v0/subject/${ id.text }/move`,
				{
					targetPageId,
					makeMainSubject,
					comment,
				},
			);
		} catch ( error ) {
			throw new Error( this.rejectedMessageOf( error ) ?? 'Error moving subject' );
		}

		if ( !response.ok ) {
			throw new Error( await this.stringFieldOf( response, 'message' ) ?? 'Error moving subject' );
		}
	}

	private rejectedMessageOf( error: unknown ): string | null {
		const message = ( error as { response?: { data?: { message?: unknown } } } )?.response?.data?.message;

		return typeof message === 'string' ? message : null;
	}

	/**
	 * The title a refused create named as one it cannot use, or null where it refused something
	 * else: a malformed body is refused with the same status, and only a refused title is named.
	 */
	private refusedPageTitleOf( error: unknown ): string | null {
		const response = ( error as { response?: { status?: unknown; data?: { pageTitle?: unknown } } } )?.response;

		if ( response?.status !== 400 ) {
			return null;
		}

		return typeof response.data?.pageTitle === 'string' ? response.data.pageTitle : null;
	}

	/**
	 * One field of an error body the server sent, or null when it sent none that reads as a string:
	 * an error response need not carry JSON at all.
	 */
	private async stringFieldOf( response: Response, field: string ): Promise<string | null> {
		try {
			const value = ( await response.json() as Record<string, unknown> )?.[ field ];

			return typeof value === 'string' ? value : null;
		} catch {
			return null;
		}
	}

	public async validateSubject(
		label: string | null,
		schemaName: SchemaName,
		statements: StatementList,
	): Promise<SubjectViolation[]> {
		return this.runValidation(
			`${ this.mediaWikiRestApiUrl }/sws/v0/subject/validate`,
			{ schema: schemaName, label, statements: statementsToJson( statements ) },
		);
	}

	public async validateSubjectUpdate(
		id: SubjectId,
		label: string | null,
		statements: StatementList,
	): Promise<SubjectViolation[]> {
		return this.runValidation(
			`${ this.mediaWikiRestApiUrl }/sws/v0/subject/${ id.text }/validate`,
			{ label, statements: statementsToJson( statements ) },
		);
	}

	private async runValidation( url: string, payload: Record<string, unknown> ): Promise<SubjectViolation[]> {
		let response: Response;
		try {
			response = await this.httpClient.post( url, payload );
		} catch {
			// 400/404 (malformed input / missing schema) reject in ProductionHttpClient — no live feedback, fall back silently.
			return [];
		}

		if ( !response.ok ) {
			return [];
		}

		const violations = parseViolations( await response.json() );
		return violations ?? [];
	}

}
